create table wksp_dtesc.sgt_zonas (
    id          number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment by 1 cache
    20 noorder nocycle nokeep noscale not null enable,
    nombre      varchar2(50 byte),
    parent_id   number,
    descripcion varchar2(4000 byte)
);

alter table wksp_dtesc.sgt_zonas
    add constraint chk_is_not_null_nombre check ( nombre is not null ) enable;

alter table wksp_dtesc.sgt_zonas add primary key ( id )
    using index enable;


